import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { UserService } from '../user/user.service';

@Injectable()
export class AcademyProfileGuard implements CanActivate {
  constructor(private userService: UserService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToRpc().getData();
    const user = request.user;

    if (!user) {
      throw new UnauthorizedException('No user found in request');
    }

    // Ensure user has Academy profile
    try {
      const profile = await this.userService.getOrCreateProfile(user);
      request.academyProfile = profile;
      return true;
    } catch (error) {
      throw new UnauthorizedException('Failed to get Academy profile');
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ContentType } from '../generated/client';

export interface StreamingOptions {
  quality?: 'low' | 'medium' | 'high' | 'auto';
  format?: 'mp4' | 'webm' | 'hls' | 'dash';
  bandwidth?: number; // in kbps
  resolution?: string; // e.g., '1920x1080'
}

export interface ContentMetadata {
  duration?: number;
  fileSize?: number;
  mimeType?: string;
  thumbnailUrl?: string;
  subtitles?: string[];
  chapters?: Array<{ title: string; startTime: number }>;
}

@Injectable()
export class ContentDeliveryService {
  private readonly logger = new Logger(ContentDeliveryService.name);

  /**
   * Generate adaptive streaming URLs for video content
   */
  async generateAdaptiveStreamingUrl(
    contentUrl: string,
    options: StreamingOptions = {},
  ): Promise<{ url: string; metadata: ContentMetadata }> {
    const { quality = 'auto', format = 'hls', bandwidth } = options;

    // This would integrate with your CDN/streaming service
    // Examples: AWS CloudFront, Cloudflare, Vimeo, etc.

    let streamingUrl = contentUrl;

    // Add quality parameters
    if (quality !== 'auto') {
      streamingUrl += `?quality=${quality}`;
    }

    // Add format parameters
    if (format === 'hls') {
      streamingUrl = streamingUrl.replace(/\.[^/.]+$/, '.m3u8');
    } else if (format === 'dash') {
      streamingUrl = streamingUrl.replace(/\.[^/.]+$/, '.mpd');
    }

    // Add bandwidth optimization
    if (bandwidth) {
      const separator = streamingUrl.includes('?') ? '&' : '?';
      streamingUrl += `${separator}bandwidth=${bandwidth}`;
    }

    this.logger.log(`Generated streaming URL: ${streamingUrl}`);

    return {
      url: streamingUrl,
      metadata: {
        duration: 0, // Would be extracted from video metadata
        fileSize: 0, // Would be calculated
        mimeType: this.getMimeType(format),
        thumbnailUrl: this.generateThumbnailUrl(contentUrl),
        subtitles: [],
        chapters: [],
      },
    };
  }

  /**
   * Generate CDN-optimized URLs for different content types
   */
  async generateCdnUrl(
    contentUrl: string,
    contentType: ContentType,
    options: { region?: string; cache?: boolean } = {},
  ): Promise<string> {
    const { region = 'global', cache = true } = options;

    // This would integrate with your CDN service
    // Examples: AWS CloudFront, Cloudflare, etc.

    let cdnUrl = contentUrl;

    // Add CDN domain
    if (process.env.CDN_DOMAIN) {
      cdnUrl = cdnUrl.replace(
        /^https?:\/\/[^\/]+/,
        `https://${process.env.CDN_DOMAIN}`,
      );
    }

    // Add region-specific optimization
    if (region !== 'global') {
      const separator = cdnUrl.includes('?') ? '&' : '?';
      cdnUrl += `${separator}region=${region}`;
    }

    // Add caching headers
    if (cache) {
      const separator = cdnUrl.includes('?') ? '&' : '?';
      cdnUrl += `${separator}cache=1`;
    }

    this.logger.log(`Generated CDN URL: ${cdnUrl}`);

    return cdnUrl;
  }

  /**
   * Generate pre-signed URLs for secure content access
   */
  async generatePresignedUrl(
    contentUrl: string,
    expiresIn: number = 3600, // 1 hour default
  ): Promise<string> {
    // This would integrate with your cloud storage service
    // Examples: AWS S3, Google Cloud Storage, etc.

    // For now, return the original URL
    // In production, you would generate a pre-signed URL
    this.logger.log(`Generated pre-signed URL for: ${contentUrl}`);

    return contentUrl;
  }

  /**
   * Optimize content delivery based on user's network conditions
   */
  async optimizeForNetwork(
    contentUrl: string,
    contentType: ContentType,
    networkInfo: {
      bandwidth: number; // in kbps
      latency: number; // in ms
      connectionType: 'wifi' | '4g' | '3g' | '2g';
    },
  ): Promise<string> {
    const { bandwidth, latency, connectionType } = networkInfo;

    let optimizedUrl = contentUrl;

    // Adjust quality based on bandwidth
    if (bandwidth < 1000) {
      // Less than 1 Mbps
      optimizedUrl += '?quality=low';
    } else if (bandwidth < 5000) {
      // Less than 5 Mbps
      optimizedUrl += '?quality=medium';
    } else {
      optimizedUrl += '?quality=high';
    }

    // Add connection-specific optimizations
    if (connectionType === '2g' || connectionType === '3g') {
      optimizedUrl += '&mobile=1';
    }

    // Add latency compensation
    if (latency > 100) {
      optimizedUrl += '&buffer=2';
    }

    this.logger.log(`Optimized URL for network: ${optimizedUrl}`);

    return optimizedUrl;
  }

  /**
   * Generate content preview URLs
   */
  async generatePreviewUrl(
    contentUrl: string,
    contentType: ContentType,
  ): Promise<string> {
    if (contentType === ContentType.VIDEO) {
      // Generate video thumbnail or short preview
      return `${contentUrl}?preview=1&duration=30`;
    } else if (contentType === ContentType.PDF) {
      // Generate PDF preview (first few pages)
      return `${contentUrl}?preview=1&pages=1-3`;
    }

    return contentUrl;
  }

  /**
   * Track content delivery metrics
   */
  async trackDeliveryMetrics(
    contentId: number,
    metrics: {
      loadTime: number;
      bufferTime: number;
      quality: string;
      errors: string[];
    },
  ): Promise<void> {
    this.logger.log(
      `Tracking delivery metrics for content ${contentId}:`,
      metrics,
    );

    // In production, you would store these metrics in a database
    // for analytics and optimization purposes
  }

  private getMimeType(format: string): string {
    const mimeTypes = {
      mp4: 'video/mp4',
      webm: 'video/webm',
      hls: 'application/x-mpegURL',
      dash: 'application/dash+xml',
      pdf: 'application/pdf',
    };

    return mimeTypes[format] || 'application/octet-stream';
  }

  private generateThumbnailUrl(videoUrl: string): string {
    // Generate thumbnail URL for video content
    // This would integrate with your video processing service
    return videoUrl.replace(/\.[^/.]+$/, '_thumb.jpg');
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateCourseModuleDto } from './dto/create-course-module.dto';
import { UpdateCourseModuleDto } from './dto/update-course-module.dto';
import { AuthenticatedUser, UserService } from 'src/user/user.service';

// The verified user object passed from the API Gateway

@Injectable()
export class CourseModulesService {
  constructor(
    private prisma: PrismaService,
    private userService: UserService,
  ) {}

  async create(dto: CreateCourseModuleDto, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    // Find the course to check for ownership
    const course = await this.prisma.course.findUnique({
      where: { id: dto.courseId },
    });
    if (!course) throw new NotFoundException('Course not found');

    // AUTHORIZATION: User must be the course instructor or an admin.
    const isInstructor = course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (!isInstructor && !isAdmin) {
      throw new ForbiddenException(
        'You do not have permission to add a module to this course.',
      );
    }

    return await this.prisma.module.create({ data: dto });
  }

  async findAll(user: AuthenticatedUser, query: any = {}) {
    const academyProfile = await this.userService.getOrCreateProfile(user);

    // VISIBILITY: Non-admins only see modules of published courses or courses they instruct
    const page = Number(query.page) || 1;
    const pageSize = Number(query.pageSize) || 10;
    const skip = (page - 1) * pageSize;

    const where: any = {};
    if (academyProfile.role !== 'ADMIN') {
      where.OR = [
        { course: { status: 'PUBLISHED' } },
        { course: { instructorId: user.firebaseId } },
      ];
    }

    const [modules, total] = await Promise.all([
      this.prisma.module.findMany({
        where,
        skip,
        take: pageSize,
        include: {
          course: {
            select: {
              id: true,
              title: true,
              status: true,
              instructorId: true,
            },
          },
        },
        orderBy: { createdAt: 'desc' },
      }),
      this.prisma.module.count({ where }),
    ]);

    return {
      items: modules,
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
    };
  }

  async findAllByCourse(
    courseId: number,
    user: AuthenticatedUser,
    query: any = {},
  ) {
    console.log(`=== Accessing Course Modules ===`);
    console.log(`User ID: ${user.firebaseId}`);
    console.log(`Course ID: ${courseId}`);

    const course = await this.prisma.course.findUnique({
      where: { id: courseId },
    });
    if (!course) throw new NotFoundException('Course not found');

    // VISIBILITY CHECK
    const academyProfile = await this.userService.getOrCreateProfile(user);
    const isInstructor = course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (course.status !== 'PUBLISHED' && !isInstructor && !isAdmin) {
      throw new ForbiddenException(
        'You generally do not have permission to view content of this course.',
      );
    }

    const page = Number(query.page) || 1;
    const pageSize = Number(query.pageSize) || 10;
    const skip = (page - 1) * pageSize;

    const [modules, total] = await Promise.all([
      this.prisma.module.findMany({
        where: { courseId },
        skip,
        take: pageSize,
        include: {
          lessons: {
            select: {
              id: true,
              title: true,
              type: true,
              maxScore: true,
              dueDate: true,
              order: true,
              createdAt: true,
              updatedAt: true,
            },
            orderBy: { order: 'asc' },
          },
          exercises: {
            select: {
              id: true,
              title: true,
              type: true,
              points: true,
              order: true,
            },
            orderBy: { order: 'asc' },
          },
        },
        orderBy: { createdAt: 'asc' },
      }),
      this.prisma.module.count({ where: { courseId } }),
    ]);

    return {
      items: modules,
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
    };
  }

  async findOne(id: number, user: AuthenticatedUser) {
    const module = await this.prisma.module.findUnique({
      where: { id },
      include: {
        lessons: { orderBy: { order: 'asc' } },
        exercises: { orderBy: { order: 'asc' } },
        course: true,
      },
    });
    if (!module) throw new NotFoundException('Module not found');

    // AUTHORIZATION: Reuse the course-level check
    // This ensures that if the course is not accessible, the module is not accessible
    await this.findAllByCourse(module.course.id, user);

    const { course, ...moduleData } = module;
    return moduleData;
  }

  async update(
    id: number,
    dto: UpdateCourseModuleDto,
    user: AuthenticatedUser,
  ) {
    // Find the module and its parent course for ownership check
    const academyProfile = await this.userService.getOrCreateProfile(user);
    const module = await this.prisma.module.findUnique({
      where: { id },
      include: { course: true },
    });
    if (!module) throw new NotFoundException('Module not found');

    // AUTHORIZATION: User must be the course instructor or an admin.
    const isInstructor = module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (!isInstructor && !isAdmin) {
      throw new ForbiddenException(
        'You do not have permission to update this module.',
      );
    }

    return await this.prisma.module.update({
      where: { id },
      data: dto,
    });
  }

  async remove(id: number, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    const module = await this.prisma.module.findUnique({
      where: { id },
      include: { course: true },
    });
    if (!module) throw new NotFoundException('Module not found');

    // AUTHORIZATION: User must be the course instructor or an admin.
    const isInstructor = module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (!isInstructor && !isAdmin) {
      throw new ForbiddenException(
        'You do not have permission to delete this module.',
      );
    }

    return await this.prisma.module.delete({ where: { id } });
  }

  async findOneForInstructor(id: number, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    const module = await this.prisma.module.findUnique({
      where: { id },
      include: {
        course: {
          select: { instructorId: true, title: true },
        },
        lessons: {
          include: {
            contents: true,
            exercises: true,
          },
          orderBy: { order: 'asc' },
        },
        exercises: {
          orderBy: { order: 'asc' },
        },
      },
    });

    if (!module) throw new NotFoundException('Module not found');

    const isInstructor = module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (!isInstructor && !isAdmin) {
      throw new ForbiddenException(
        'You do not have permission to view this module in instructor mode.',
      );
    }

    return module;
  }
}

import {
  BadRequestException,
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateCourseDto } from './dto/create-course.dto';
import { UpdateCourseDto } from './dto/update-course.dto';
import { AcademyRole, CourseStatus, LessonType } from '../generated/client';
import { AuthenticatedUser, UserService } from '../user/user.service';

type FindAllQuery = {
  page?: number;
  pageSize?: number;
  status?: CourseStatus;
  instructorId?: string;
  category?: string;
  difficulty?: string; // Add this
  targetLevel?: string; // Add this
  q?: string; // search in title/description
};

@Injectable()
export class CoursesService {
  constructor(
    private prisma: PrismaService,
    private userService: UserService,
  ) {}

  async create(dto: CreateCourseDto, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    if (
      academyProfile.role !== AcademyRole.INSTRUCTOR &&
      academyProfile.role !== AcademyRole.ADMIN
    ) {
      throw new ForbiddenException(
        'You do not have permission to create a course.',
      );
    }

    const instructorId = user.firebaseId;

    const exists = await this.prisma.course.findFirst({
      where: { title: dto.title, instructorId: instructorId },
    });
    if (exists)
      throw new BadRequestException(
        'You already have a course with this title',
      );

    // Validate URL if provided
    if (dto.thumbnail) {
      try {
        new URL(dto.thumbnail);
      } catch (e) {
        throw new BadRequestException('Invalid thumbnail URL');
      }
    }

    // Create course with only the fields that exist in the Prisma model
    // Automatically set status to PUBLISHED for instructors to make courses visible on homepage
    const course = await this.prisma.course.create({
      data: {
        title: dto.title,
        shortDescription: dto.shortDescription,
        longDescription: dto.longDescription,
        thumbnail: dto.thumbnail,
        category: dto.category,
        // Automatically set to DRAFT to allow teacher to add content before approval
        status: CourseStatus.DRAFT,
        skills: dto.skills || [],
        conceptsLearned: dto.conceptsLearned || [],
        outcomes: (dto as any).outcomes || [],
        estimatedTime: dto.estimatedTime,
        targetLevel: dto.targetLevel,
        enrolledNum: dto.enrolledNum || 0,
        rating: dto.rating,
        price: dto.price,
        prerequisites: dto.prerequisites || [],
        languages: dto.languages || [],
        instructorId: instructorId,
      },
    });

    // Create a default cohort for the course only if requested
    if (dto.createDefaultCohort) {
      try {
        await this.prisma.cohort.create({
          data: {
            name: `${course.title} - Default Cohort`,
            courseId: course.id,
            startDate: new Date(),
            endDate: new Date(
              new Date().setFullYear(new Date().getFullYear() + 1),
            ), // 1 year from now
          },
        });
      } catch (cohortError) {
        console.error('Failed to create default cohort:', cohortError);
        // Don't throw an error here as the course creation should still succeed
      }
    }

    return course;
  }

  // --- NEW: Create a course with modules and lessons ---
  async createCourseWithStructure(
    dto: CreateCourseDto & {
      modules: Array<{
        title: string;
        description: string;
        lessons: Array<{
          title: string;
          type: LessonType;
        }>;
      }>;
    },
    user: AuthenticatedUser,
  ) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    if (
      academyProfile.role !== AcademyRole.INSTRUCTOR &&
      academyProfile.role !== AcademyRole.ADMIN
    ) {
      throw new ForbiddenException(
        'You do not have permission to create a course.',
      );
    }

    const instructorId = user.firebaseId;

    // Check if course with this title already exists
    const exists = await this.prisma.course.findFirst({
      where: { title: dto.title, instructorId: instructorId },
    });
    if (exists)
      throw new BadRequestException(
        'You already have a course with this title',
      );

    // Create course with modules and lessons in a transaction
    const course = await this.prisma.$transaction(async (prisma) => {
      // Create the course
      const newCourse = await prisma.course.create({
        data: {
          title: dto.title,
          shortDescription: dto.shortDescription,
          longDescription: dto.longDescription,
          category: dto.category,
          status: CourseStatus.DRAFT, // Start as draft
          skills: dto.skills || [],
          conceptsLearned: dto.conceptsLearned || [],
          outcomes: (dto as any).outcomes || [],
          estimatedTime: dto.estimatedTime,
          targetLevel: dto.targetLevel,
          enrolledNum: dto.enrolledNum || 0,
          rating: dto.rating,
          price: dto.price,
          prerequisites: dto.prerequisites || [],
          languages: dto.languages || [],
          instructorId: instructorId,
        },
      });

      // Create a default cohort for the course only if requested
      if (dto.createDefaultCohort) {
        await prisma.cohort.create({
          data: {
            name: `${newCourse.title} - Default Cohort`,
            courseId: newCourse.id,
            startDate: new Date(),
            endDate: new Date(
              new Date().setFullYear(new Date().getFullYear() + 1),
            ), // 1 year from now
          },
        });
      }

      // Create modules and lessons
      if (dto.modules && dto.modules.length > 0) {
        for (const moduleData of dto.modules) {
          const newModule = await prisma.module.create({
            data: {
              title: moduleData.title,
              description: moduleData.description,
              courseId: newCourse.id,
            },
          });

          // Create lessons for this module
          if (moduleData.lessons && moduleData.lessons.length > 0) {
            for (const lessonData of moduleData.lessons) {
              await prisma.lesson.create({
                data: {
                  title: lessonData.title,
                  type: lessonData.type,
                  moduleId: newModule.id,
                },
              });
            }
          }
        }
      }

      return newCourse;
    });

    return course;
  }

  // REFACTORED: To enrich data with user info
  async findAll(query: FindAllQuery, user?: AuthenticatedUser) {
    try {
      // Build the where clause
      const where: any = {};

      // Check if user is admin
      let isAdmin = false;
      if (user) {
        const profile = await this.userService.getOrCreateProfile(user);
        isAdmin = profile.role === AcademyRole.ADMIN;
      }

      // Enforce visibility rules
      if (isAdmin) {
        if (query.status) where.status = query.status;
        if (query.instructorId) where.instructorId = query.instructorId;
      } else if (user && query.instructorId === user.firebaseId) {
        // Instructor looking at their own courses - allow filtering by any status
        if (query.status) where.status = query.status;
        where.instructorId = query.instructorId;
      } else {
        // Public view or looking at someone else's courses - only show PUBLISHED
        where.status = CourseStatus.PUBLISHED;
        if (query.instructorId) where.instructorId = query.instructorId;
      }

      if (query.category) where.category = query.category;
      if (query.targetLevel) where.targetLevel = query.targetLevel;
      if (query.difficulty) where.targetLevel = query.difficulty;
      if (query.q) {
        where.OR = [
          { title: { contains: query.q, mode: 'insensitive' } },
          { shortDescription: { contains: query.q, mode: 'insensitive' } },
          { longDescription: { contains: query.q, mode: 'insensitive' } },
        ];
      }

      // Handle pagination
      const page = Number(query.page) || 1;
      const pageSize = Number(query.pageSize) || 10;
      const skip = (page - 1) * pageSize;

      const [courses, total] = await Promise.all([
        this.prisma.course.findMany({
          where,
          skip,
          take: pageSize,
          orderBy: { createdAt: 'desc' },
          include: {
            _count: {
              select: {
                modules: true,
                enrollments: true,
              },
            },
            profile: {
              select: {
                bio: true,
                expertise: true,
                specialization: true,
                role: true,
              },
            },
            // Conditional include for full content when pending approval
            ...(query.status === CourseStatus.PENDING_APPROVAL
              ? {
                  modules: {
                    orderBy: { createdAt: 'asc' },
                    include: {
                      lessons: {
                        orderBy: { order: 'asc' },
                        include: {
                          contents: {
                            orderBy: { createdAt: 'asc' },
                          },
                          exercises: {
                            orderBy: { order: 'asc' },
                          },
                        },
                      },
                      exercises: {
                        orderBy: { order: 'asc' },
                      },
                    },
                  },
                }
              : {}),
          },
        }),
        this.prisma.course.count({ where }),
      ]);

      // --- Data Enrichment Step ---
      // Get unique instructor IDs from the courses
      const instructorIds = [...new Set(courses.map((c) => c.instructorId))];

      // Fetch all required instructors in a single batch call from Auth Service
      const authInstructors =
        await this.userService.getUsersByIds(instructorIds);

      // Map everything back to response objects
      const items = courses.map((course: any) => {
        const authInfo = authInstructors.find(
          (i: any) => i.firebaseId === course.instructorId,
        );

        return {
          ...course,
          modulesCount: course._count?.modules || 0,
          enrolledNum: course._count?.enrollments || course.enrolledNum || 0,
          instructor: authInfo
            ? {
                ...authInfo,
                profile: course.profile,
              }
            : null,
          // Remove the raw profile and _count property from the root level of the item
          profile: undefined,
          _count: undefined,
        };
      });

      let statusCounts = {};
      if (isAdmin) {
        const counts = await this.prisma.course.groupBy({
          by: ['status'],
          _count: true,
        });
        statusCounts = counts.reduce((acc, curr) => {
          acc[curr.status] = curr._count;
          return acc;
        }, {});
      }

      return {
        items,
        total,
        page,
        pageSize,
        totalPages: Math.ceil(total / pageSize),
        statusCounts: isAdmin ? statusCounts : undefined,
      };
    } catch (error) {
      console.error('Error in findAll:', error);
      throw error;
    }
  }

  // REFACTORED: Use string ID and enrich data
  async findOne(id: number, user?: AuthenticatedUser) {
    const course = await this.prisma.course.findUnique({
      where: { id },
      include: {
        modules: {
          orderBy: { createdAt: 'asc' },
          include: {
            lessons: {
              orderBy: { order: 'asc' },
              include: {
                contents: {
                  orderBy: { createdAt: 'asc' },
                },
                exercises: {
                  orderBy: { order: 'asc' },
                },
              },
            },
            exercises: {
              orderBy: { order: 'asc' },
            },
          },
        },
        profile: {
          select: {
            bio: true,
            expertise: true,
            specialization: true,
            role: true,
          },
        },
      },
    });
    if (!course) throw new NotFoundException('Course not found');

    // Visibility Check: If not published, only Admin or Owner can view
    if (course.status !== CourseStatus.PUBLISHED) {
      let isAllowed = false;
      if (user) {
        const profile = await this.userService.getOrCreateProfile(user);
        if (
          profile.role === AcademyRole.ADMIN ||
          course.instructorId === user.firebaseId
        ) {
          isAllowed = true;
        }
      }

      if (!isAllowed) {
        throw new NotFoundException('Course not found');
      }
    }

    // Count enrollments for this course
    const enrollmentCount = await this.prisma.enrollment.count({
      where: {
        courseId: course.id,
      },
    });

    // Enrich with instructor data
    const instructor = await this.userService.getUserById(course.instructorId);
    return {
      ...course,
      enrolledNum: enrollmentCount, // Override the stored enrolledNum with actual count
      instructor,
    };
