  // REFACTORED: Now performs an ownership check
  async update(id: number, dto: UpdateCourseDto, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    const course = await this.prisma.course.findUnique({ where: { id } });
    if (!course) throw new NotFoundException('Course not found');

    // OWNERSHIP CHECK: User must be an ADMIN or the original instructor
    if (
      academyProfile.role !== AcademyRole.ADMIN &&
      course.instructorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to edit this course',
      );
    }

    // Only an admin can re-assign an instructor
    if (dto.instructorId && academyProfile.role !== AcademyRole.ADMIN) {
      throw new ForbiddenException(
        'Only an admin can change the course instructor',
      );
    }

    if (dto.instructorId) {
      const newInstructorProfile = await this.userService.ensureProfileExists(
        dto.instructorId,
      );
      if (!newInstructorProfile) {
        throw new BadRequestException(
          'The assigned user does not exist in the Auth Service.',
        );
      }
      if (
        newInstructorProfile.role !== AcademyRole.INSTRUCTOR &&
        newInstructorProfile.role !== AcademyRole.ADMIN
      ) {
        throw new BadRequestException(
          'The assigned user is not an instructor.',
        );
      }
    }

    return await this.prisma.course.update({ where: { id }, data: dto });
  }

  // REFACTORED: Added ownership check
  async remove(id: number, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    const course = await this.prisma.course.findUnique({ where: { id } });
    if (!course) throw new NotFoundException('Course not found');

    if (
      academyProfile.role !== AcademyRole.ADMIN &&
      course.instructorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to delete this course',
      );
    }

    return await this.prisma.course.delete({ where: { id } });
  }

  async updateStatus(
    id: number,
    status: CourseStatus,
    user: AuthenticatedUser,
  ) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    const course = await this.prisma.course.findUnique({ where: { id } });
    if (!course) {
      throw new NotFoundException('Course not found');
    }

    // AUTHORIZATION: User must be an ADMIN or the instructor who owns the course.
    if (
      academyProfile.role !== AcademyRole.ADMIN &&
      course.instructorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to change the status of this course',
      );
    }

    // Your existing business logic is still valid
    if (
      course.status === CourseStatus.ARCHIVED &&
      status !== CourseStatus.ARCHIVED
    ) {
      throw new BadRequestException('Archived courses cannot be re-published');
    }

    return await this.prisma.course.update({
      where: { id },
      data: { status },
    });
  }

  // REFACTORED: Now an admin-only action
  async assignInstructor(
    id: number,
    newInstructorId: string,
    user: AuthenticatedUser,
  ) {
    // AUTHORIZATION: In this business model, we'll say only an ADMIN can re-assign a course.
    // This prevents instructors from passing courses between themselves without oversight.
    const academyProfile = await this.userService.getOrCreateProfile(user);
    if (academyProfile.role !== AcademyRole.ADMIN) {
      throw new ForbiddenException(
        'Only an administrator can assign an instructor',
      );
    }

    const course = await this.prisma.course.findUnique({ where: { id } });
    if (!course) {
      throw new NotFoundException('Course not found');
    }

    // Validate that the new instructor is a valid user with the correct role
    const newInstructorProfile =
      await this.userService.ensureProfileExists(newInstructorId);
    if (!newInstructorProfile) {
      throw new BadRequestException(
        'The assigned user does not exist in the Auth Service.',
      );
    }
    if (
      newInstructorProfile.role !== AcademyRole.INSTRUCTOR &&
      newInstructorProfile.role !== AcademyRole.ADMIN
    ) {
      throw new BadRequestException(
        'The assigned user is not a valid instructor.',
      );
    }

    return await this.prisma.course.update({
      where: { id },
      data: { instructorId: newInstructorId },
    });
  }

  // --- NEW: Get course with full structure (modules, lessons, content) ---
  async getCourseWithStructure(id: number, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    const course = await this.prisma.course.findUnique({
      where: { id },
      include: {
        modules: {
          include: {
            lessons: {
              include: {
                contents: true,
              },
            },
          },
          orderBy: {
            createdAt: 'asc',
          },
        },
      },
    });

    if (!course) throw new NotFoundException('Course not found');

    // Authorization check
    if (academyProfile.role === 'STUDENT' && course.status !== 'PUBLISHED') {
      throw new ForbiddenException('You do not have access to this course.');
    }

    if (
      academyProfile.role === (AcademyRole.INSTRUCTOR as any) &&
      course.instructorId !== user.firebaseId &&
      academyProfile.role !== (AcademyRole.ADMIN as any)
    ) {
      throw new ForbiddenException(
        'You do not have permission to view this course.',
      );
    }

    return course;
  }

  // --- NEW: Get instructor's courses with stats ---
  async getInstructorCoursesWithStats(user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    if (
      academyProfile.role !== AcademyRole.INSTRUCTOR &&
      academyProfile.role !== AcademyRole.ADMIN
    ) {
      throw new ForbiddenException(
        'You do not have permission to view courses.',
      );
    }

    const courses = await this.prisma.course.findMany({
      where: { instructorId: user.firebaseId },
      include: {
        modules: {
          include: {
            lessons: {
              include: {
                contents: true,
              },
            },
          },
        },
        _count: {
          select: {
            cohorts: true,
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
    });

    // Add stats to each course
    const coursesWithStats = await Promise.all(
      courses.map(async (course) => {
        // Count total enrollments
        const enrollments = await this.prisma.enrollment.count({
          where: {
            cohort: {
              courseId: course.id,
            },
          },
        });

        // Count total modules, lessons, and content
        const modulesCount = course.modules.length;
        const lessonsCount = course.modules.reduce(
          (sum, module) => sum + module.lessons.length,
          0,
        );
        const contentCount = course.modules.reduce(
          (sum, module) =>
            sum +
            module.lessons.reduce(
              (lessonSum, lesson) => lessonSum + lesson.contents.length,
              0,
            ),
          0,
        );

        return {
          ...course,
          stats: {
            enrollments,
            modules: modulesCount,
            lessons: lessonsCount,
            contentItems: contentCount,
          },
        };
      }),
    );

    return coursesWithStats;
  }

  async submitForApproval(id: number, user: AuthenticatedUser) {
    const course = await this.prisma.course.findUnique({ where: { id } });
    if (!course) throw new NotFoundException('Course not found');
    if (course.instructorId !== user.firebaseId) {
      throw new ForbiddenException(
        'You do not have permission to submit this course for approval',
      );
    }
    if (
      course.status !== CourseStatus.DRAFT &&
      course.status !== CourseStatus.REJECTED
    ) {
      throw new BadRequestException(
        'Only draft or rejected courses can be submitted for approval',
      );
    }

    return await this.prisma.course.update({
      where: { id },
      data: { status: CourseStatus.PENDING_APPROVAL },
    });
  }

  async approve(id: number, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    if (academyProfile.role !== AcademyRole.ADMIN) {
      throw new ForbiddenException('Only administrators can approve courses');
    }

    return await this.prisma.course.update({
      where: { id },
      data: { status: CourseStatus.PUBLISHED },
    });
  }

  async reject(id: number, reason: string, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    if (academyProfile.role !== AcademyRole.ADMIN) {
      throw new ForbiddenException('Only administrators can reject courses');
    }

    return await this.prisma.course.update({
      where: { id },
      data: {
        status: CourseStatus.REJECTED,
        rejectionReason: reason,
      },
    });
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateExerciseDto } from './dto/create-exercise.dto';
import { UpdateExerciseDto } from './dto/update-exercise.dto';
import { SubmitExerciseDto } from './dto/submit-exercise.dto';
import { GradeExerciseDto } from './dto/grade-exercise.dto';
import { AuthenticatedUser, UserService } from '../user/user.service';
import { ExerciseType, SubmissionStatus } from '../generated/client';

@Injectable()
export class ExercisesService {
  constructor(
    private prisma: PrismaService,
    private userService: UserService,
  ) {}

  async create(dto: CreateExerciseDto, user: AuthenticatedUser) {
    const academyProfile = await this.userService.getOrCreateProfile(user);

    // Validate Module ownership
    const module = await this.prisma.module.findUnique({
      where: { id: dto.moduleId },
      include: { course: true },
    });
    if (!module) throw new NotFoundException('Module not found');

    const isInstructor = module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (!isInstructor && !isAdmin) {
      throw new ForbiddenException(
        'You do not have permission to add exercises to this module.',
      );
    }

    return this.prisma.exercise.create({
      data: {
        ...dto,
      },
    });
  }

  async findAllByModule(
    moduleId: number,
    user: AuthenticatedUser,
    query: any = {},
  ) {
    await this.verifyModuleAccess(moduleId, user);

    const page = Number(query.page) || 1;
    const pageSize = Number(query.pageSize) || 10;
    const skip = (page - 1) * pageSize;

    const [exercises, total] = await Promise.all([
      this.prisma.exercise.findMany({
        where: { moduleId },
        skip,
        take: pageSize,
        orderBy: { order: 'asc' },
      }),
      this.prisma.exercise.count({ where: { moduleId } }),
    ]);

    // Strip correct answers for students
    const academyProfile = await this.userService.getOrCreateProfile(user);
    const module = await this.prisma.module.findUnique({
      where: { id: moduleId },
      include: { course: true },
    });
    if (!module) throw new NotFoundException('Module not found');

    const isInstructor = module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    let items = exercises;
    if (!isInstructor && !isAdmin) {
      items = exercises.map((ex) => {
        const { correctAnswer, ...rest } = ex;
        return rest;
      }) as any;
    }

    return {
      items,
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
    };
  }

  async findByInstructor(user: AuthenticatedUser, query: any = {}) {
    const academyProfile = await this.userService.getOrCreateProfile(user);
    if (
      academyProfile.role !== 'INSTRUCTOR' &&
      academyProfile.role !== 'ADMIN'
    ) {
      throw new ForbiddenException('Instructor role required');
    }

    const page = Number(query.page) || 1;
    const pageSize = Number(query.pageSize) || 10;
    const skip = (page - 1) * pageSize;

    const where: any = {
      module: {
        course: {
          instructorId: user.firebaseId,
        },
      },
    };

    if (query.moduleId) where.moduleId = Number(query.moduleId);
    if (query.type) where.type = query.type;

    const [exercises, total] = await Promise.all([
      this.prisma.exercise.findMany({
        where,
        skip,
        take: pageSize,
        orderBy: { createdAt: 'desc' },
        include: {
          module: {
            include: {
              course: {
                select: { id: true, title: true },
              },
            },
          },
        },
      }),
      this.prisma.exercise.count({ where }),
    ]);

    return {
      items: exercises,
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
    };
  }

  async findOne(id: number, user: AuthenticatedUser) {
    const exercise = await this.prisma.exercise.findUnique({
      where: { id },
      include: {
        module: { include: { course: true } },
        lesson: true,
      },
    });
    if (!exercise) throw new NotFoundException('Exercise not found');

    await this.verifyModuleAccess(exercise.moduleId, user);

    const academyProfile = await this.userService.getOrCreateProfile(user);
    const isInstructor =
      exercise.module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (!isInstructor && !isAdmin) {
      const { correctAnswer, ...rest } = exercise;
      return rest;
    }

    return exercise;
  }

  async update(id: number, dto: UpdateExerciseDto, user: AuthenticatedUser) {
    const exercise = await this.prisma.exercise.findUnique({
      where: { id },
      include: { module: { include: { course: true } } },
    });
    if (!exercise) throw new NotFoundException('Exercise not found');

    const academyProfile = await this.userService.getOrCreateProfile(user);
    const isInstructor =
      exercise.module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (!isInstructor && !isAdmin) {
      throw new ForbiddenException(
        'You do not have permission to update this exercise.',
      );
    }

    return this.prisma.exercise.update({
      where: { id },
      data: dto,
    });
  }

  async remove(id: number, user: AuthenticatedUser) {
    const exercise = await this.prisma.exercise.findUnique({
      where: { id },
      include: { module: { include: { course: true } } },
    });
    if (!exercise) throw new NotFoundException('Exercise not found');

    const academyProfile = await this.userService.getOrCreateProfile(user);
    const isInstructor =
      exercise.module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (!isInstructor && !isAdmin) {
      throw new ForbiddenException(
        'You do not have permission to delete this exercise.',
      );
    }

    return this.prisma.exercise.delete({ where: { id } });
  }

  async submit(id: number, dto: SubmitExerciseDto, user: AuthenticatedUser) {
    const exercise = await this.prisma.exercise.findUnique({
      where: { id },
      include: { module: { include: { course: true } } },
    });
    if (!exercise) throw new NotFoundException('Exercise not found');

    await this.verifyModuleAccess(exercise.moduleId, user);

    let isCorrect = false;
    let score = 0;
    let status: SubmissionStatus = SubmissionStatus.GRADED;

    // Auto-grading logic
    if (
      exercise.type === ExerciseType.MULTIPLE_CHOICE ||
      exercise.type === ExerciseType.TRUE_FALSE
    ) {
      // Comparison might differ based on data types (string vs object). Assuming simple equality for now.
      isCorrect = dto.answer === exercise.correctAnswer;
      score = isCorrect ? exercise.points : 0;
    } else if (exercise.type === ExerciseType.MATCHING) {
      // Logic for matching: Check if all pairs match
      // answer: [{"left": "A", "right": "1"}, ...]
      // correctAnswer: [{"left": "A", "right": "1"}, ...]
      const answerPairs = Array.isArray(dto.answer) ? dto.answer : [];
      const correctPairs = Array.isArray(exercise.correctAnswer)
        ? exercise.correctAnswer
        : [];

      // Simple check: stringify and compare sorted or use validation util
      // For now, strict JSON equality
      if (JSON.stringify(answerPairs) === JSON.stringify(correctPairs)) {
        isCorrect = true;
        score = exercise.points;
      }
    } else if (exercise.type === ExerciseType.SHORT_TEXT) {
      status = SubmissionStatus.PENDING_REVIEW;
      score = 0; // To be determined
    }

    // Save submission
    // We use upsert to allow re-submission or we can block strict re-submissions
    // Prompt didn't specify, so Upserting (taking latest) seems user-friendly for "Practice"
    return this.prisma.exerciseSubmission.upsert({
      where: {
        userId_exerciseId: {
          userId: user.firebaseId,
          exerciseId: id,
        },
      },
      update: {
        answer: dto.answer,
        isCorrect,
        score,
        status,
        updatedAt: new Date(),
        attemptCount: { increment: 1 },
      },
      create: {
        userId: user.firebaseId,
        exerciseId: id,
        answer: dto.answer,
        isCorrect,
        score,
        status,
      },
    });
  }

  async grade(
    submissionId: number,
    dto: GradeExerciseDto,
    user: AuthenticatedUser,
  ) {
    const submission = await this.prisma.exerciseSubmission.findUnique({
      where: { id: submissionId },
      include: {
        exercise: { include: { module: { include: { course: true } } } },
      },
    });
    if (!submission) throw new NotFoundException('Submission not found');

    const academyProfile = await this.userService.getOrCreateProfile(user);
    const isInstructor =
      submission.exercise.module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (!isInstructor && !isAdmin) {
      throw new ForbiddenException(
        'You do not have permission to grade this exercise.',
      );
    }

    return this.prisma.exerciseSubmission.update({
      where: { id: submissionId },
      data: {
        isCorrect: dto.isCorrect,
        score: dto.score,
        feedback: dto.feedback,
        status: SubmissionStatus.GRADED,
      },
    });
  }

  // Helper to verify student access
  private async verifyModuleAccess(moduleId: number, user: AuthenticatedUser) {
    const module = await this.prisma.module.findUnique({
      where: { id: moduleId },
      include: { course: true },
    });
    if (!module) throw new NotFoundException('Module not found');

    const academyProfile = await this.userService.getOrCreateProfile(user);
    const isInstructor = module.course.instructorId === user.firebaseId;
    const isAdmin = academyProfile.role === 'ADMIN';

    if (isInstructor || isAdmin) return;

    // Check enrollment
    const directEnrollment = await this.prisma.enrollment.findFirst({
      where: {
        userId: user.firebaseId,
        courseId: module.courseId,
        cohortId: null,
        status: 'ACTIVE',
      },
    });

    const cohortEnrollment = await this.prisma.enrollment.findFirst({
      where: {
        userId: user.firebaseId,
        cohort: { courseId: module.courseId },
        status: 'ACTIVE',
      },
    });

    if (!directEnrollment && !cohortEnrollment) {
      throw new ForbiddenException(
        'You must be enrolled in this course to access exercises.',
      );
    }
  }
}

